create policy property_staff_access_v3_employee_read on public.property_staff_access_v3 for select to authenticated using (employee_user_id = (select auth.uid())); create policy property_staff_access_v3_admin_read on public.property_staff_access_v3 for select to authenticated using ((select auth.jwt()->'app_metadata'->>'role') = 'root' or ((select auth.jwt()->'app_metadata'->>'role') = 'admin' and organization_id::text = (select auth.jwt()->'app_metadata'->>'organization_id')));
